UPDATE `canvas_project`
project_no = #{projectNo}, user_id = #{userId}, title = #{title}, document_json = #{documentJson}, node_count = #{nodeCount}, file_count = #{fileCount}, document_bytes = #{documentBytes}, version = #{version}, created_at = #{createdAt}, updated_at = #{updatedAt}, deleted_at = #{deletedAt},
