UPDATE `canvas_project`
SET title = #{title},
    document_json = #{documentJson},
    document_bytes = #{documentBytes},
    node_count = #{nodeCount},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL

UPDATE `canvas_project`
SET deleted_at = #{deletedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
